pub struct S {
    x: u8,
    y: [u8; 4],
}

pub fn the_loop(s: &mut S, next_in: &mut &[u8]) -> bool {
    loop {
        let result = f(&mut s.x, *next_in, &mut s.y);
        let n = result.1;
        let done = result.0;
        *next_in = &next_in[n..];
        if done || next_in.is_empty() {
            return done;
        }
    }
}
